CREATE OR REPLACE VIEW secondhand.market.listing_obs
(site, kind, brand_norm, title_terms, condition, price_cents, likes, listed_at, sold, sold_at, read_at, observation_id)
COMMENT 'Stored listing reads with nullable page fields. Only may_model true evidence, never Dupe, live: reads within retention.'
AS SELECT
  o.site AS site,
  get_json_object(o.payload, '$.category') AS kind,
  lower(trim(get_json_object(o.payload, '$.brand'))) AS brand_norm,
  CASE WHEN get_json_object(o.payload, '$.title') IS NULL THEN cast(NULL AS ARRAY<STRING>)
    ELSE filter(split(lower(coalesce(get_json_object(o.payload, '$.title'), '')), r'[^\p{L}\p{N}]+'), word -> word <> '') END AS title_terms,
  get_json_object(o.payload, '$.condition') AS condition,
  try_cast(get_json_object(o.payload, '$.price_cents') AS BIGINT) AS price_cents,
  try_cast(get_json_object(o.payload, '$.likes') AS BIGINT) AS likes,
  try_cast(get_json_object(o.payload, '$.listed_at') AS TIMESTAMP) AS listed_at,
  try_cast(get_json_object(o.payload, '$.sold') AS BOOLEAN) AS sold,
  try_cast(get_json_object(o.payload, '$.sold_date') AS TIMESTAMP) AS sold_at,
  o.observed_at AS read_at,
  o.id AS observation_id
FROM secondhand.core.observation o
JOIN secondhand.core.evidence e ON o.evidence_id = e.id
WHERE e.may_model = true AND o.site <> 'dupe' AND o.data LIKE 'live:%'
  AND o.kind = 'listing'
  AND (o.keep_until IS NULL OR o.keep_until > current_timestamp());

CREATE OR REPLACE FUNCTION secondhand.market.market_min_n()
RETURNS INT
COMMENT 'Minimum count from the global champion scalar, or prior 8. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN coalesce((SELECT cast(get_json_object(value_or_hyperparams, '$') AS INT)
  FROM secondhand.core.param
  WHERE name = 'market_min_n' AND scope = '{}' AND status = 'champion'
  ORDER BY version DESC
  LIMIT 1), 8);

CREATE OR REPLACE VIEW secondhand.market.coverage
(site, kind, rows, oldest_read, newest_read)
COMMENT 'Stored listing counts and read dates by site and page category. Only may_model true evidence, never Dupe, live: reads within retention.'
AS SELECT site, kind, count(*) AS rows,
  CASE WHEN count(*) < secondhand.market.market_min_n() THEN NULL ELSE min(read_at) END AS oldest_read,
  max(read_at) AS newest_read
FROM secondhand.market.listing_obs
GROUP BY site, kind;

CREATE OR REPLACE FUNCTION secondhand.market.asks(term STRING, site STRING, days INT)
RETURNS TABLE (site STRING, n BIGINT, p10_cents BIGINT, p50_cents BIGINT, p90_cents BIGINT, likes_per_listing DOUBLE, sold_share DOUBLE, as_of TIMESTAMP)
COMMENT 'Asking-price percentiles in whole cents, reported likes and sold share over listing reads in the day window. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN
WITH terms AS (SELECT filter(split(lower(coalesce(asks.term, '')), r'[^\p{L}\p{N}]+'), word -> word <> '') AS words),
stats AS (
  SELECT count(*) AS n,
    cast(round(percentile(price_cents, 0.1)) AS BIGINT) AS p10_cents,
    cast(round(percentile(price_cents, 0.5)) AS BIGINT) AS p50_cents,
    cast(round(percentile(price_cents, 0.9)) AS BIGINT) AS p90_cents,
    avg(cast(likes AS DOUBLE)) AS likes_per_listing,
    cast(count_if(sold = true) AS DOUBLE) / nullif(count(*), 0) AS sold_share,
    max(o.read_at) AS as_of
  FROM secondhand.market.listing_obs o CROSS JOIN terms
  WHERE (asks.site = 'all' OR o.site = asks.site)
    AND size(words) > 0 AND forall(words, word -> array_contains(o.title_terms, word))
    AND o.read_at >= timestampadd(DAY, -asks.days, current_timestamp())
    AND o.read_at <= current_timestamp()
)
SELECT asks.site AS site, n,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE p10_cents END AS p10_cents,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE p50_cents END AS p50_cents,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE p90_cents END AS p90_cents,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE likes_per_listing END AS likes_per_listing,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE sold_share END AS sold_share,
  as_of
FROM stats;

CREATE OR REPLACE FUNCTION secondhand.market.term_trend(term STRING, site STRING, weeks INT)
RETURNS TABLE (week TIMESTAMP, site STRING, n BIGINT, p50_cents BIGINT, likes_per_listing DOUBLE, as_of TIMESTAMP)
COMMENT 'Weekly median asks in whole cents and reported likes for a title term in the week window. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN
WITH terms AS (SELECT filter(split(lower(coalesce(term_trend.term, '')), r'[^\p{L}\p{N}]+'), word -> word <> '') AS words),
stats AS (
  SELECT date_trunc('WEEK', o.read_at) AS week, count(*) AS n,
    cast(round(percentile(price_cents, 0.5)) AS BIGINT) AS p50_cents,
    avg(cast(likes AS DOUBLE)) AS likes_per_listing,
    max(o.read_at) AS as_of
  FROM secondhand.market.listing_obs o CROSS JOIN terms
  WHERE (term_trend.site = 'all' OR o.site = term_trend.site)
    AND size(words) > 0 AND forall(words, word -> array_contains(o.title_terms, word))
    AND o.read_at >= timestampadd(WEEK, -term_trend.weeks, current_timestamp())
    AND o.read_at <= current_timestamp()
  GROUP BY date_trunc('WEEK', o.read_at)
)
SELECT week, term_trend.site AS site, n,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE p50_cents END AS p50_cents,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE likes_per_listing END AS likes_per_listing,
  as_of
FROM stats;

CREATE OR REPLACE FUNCTION secondhand.market.top_terms(kind STRING, site STRING, days INT, k INT)
RETURNS TABLE (term STRING, site STRING, n BIGINT, p50_cents BIGINT, likes_per_listing DOUBLE, as_of TIMESTAMP)
COMMENT 'The k most frequent title words by listing count for a page category and day window, with median asks. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN
WITH expanded AS (
  SELECT explode(array_distinct(o.title_terms)) AS term, o.price_cents, o.likes, o.read_at
  FROM secondhand.market.listing_obs o
  WHERE (top_terms.site = 'all' OR o.site = top_terms.site)
    AND o.kind = top_terms.kind
    AND o.read_at >= timestampadd(DAY, -top_terms.days, current_timestamp())
    AND o.read_at <= current_timestamp()
),
stats AS (
  SELECT term, count(*) AS n,
    cast(round(percentile(price_cents, 0.5)) AS BIGINT) AS p50_cents,
    avg(cast(likes AS DOUBLE)) AS likes_per_listing,
    max(read_at) AS as_of
  FROM expanded GROUP BY term
),
ranked AS (SELECT *, row_number() OVER (ORDER BY n DESC, term) AS position FROM stats)
SELECT term, top_terms.site AS site, n,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE p50_cents END AS p50_cents,
  CASE WHEN n < secondhand.market.market_min_n() THEN NULL ELSE likes_per_listing END AS likes_per_listing,
  as_of
FROM ranked WHERE position <= top_terms.k
ORDER BY n DESC, term;

CREATE OR REPLACE FUNCTION secondhand.market.sell_through(kind STRING, site STRING)
RETURNS TABLE (site STRING, kind STRING, n_listed BIGINT, n_sold BIGINT, sold_share DOUBLE, median_days_to_sell DOUBLE, as_of TIMESTAMP)
COMMENT 'Observed sold over listed reads for a page category, plus median elapsed days from listing to sale. n_listed is the guard count. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN
WITH stats AS (
  SELECT count(*) AS n_listed, count_if(sold = true) AS n_sold,
    cast(count_if(sold = true) AS DOUBLE) / nullif(count(*), 0) AS sold_share,
    percentile(CASE WHEN sold = true AND sold_at >= listed_at
      THEN timestampdiff(SECOND, listed_at, sold_at) / 86400.0 END, 0.5) AS median_days_to_sell,
    max(o.read_at) AS as_of
  FROM secondhand.market.listing_obs o
  WHERE (sell_through.site = 'all' OR o.site = sell_through.site)
    AND o.kind = sell_through.kind
)
SELECT sell_through.site AS site, sell_through.kind AS kind, n_listed,
  CASE WHEN n_listed < secondhand.market.market_min_n() THEN NULL ELSE n_sold END AS n_sold,
  CASE WHEN n_listed < secondhand.market.market_min_n() THEN NULL ELSE sold_share END AS sold_share,
  CASE WHEN n_listed < secondhand.market.market_min_n() THEN NULL ELSE median_days_to_sell END AS median_days_to_sell,
  as_of
FROM stats;

CREATE OR REPLACE FUNCTION secondhand.market.coverage_now()
RETURNS TABLE (site STRING, kind STRING, rows BIGINT, oldest_read TIMESTAMP, newest_read TIMESTAMP)
COMMENT 'Current coverage by site and page category, with rows as count and newest_read as freshness. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN SELECT site, kind, rows, oldest_read, newest_read FROM secondhand.market.coverage;

CREATE OR REPLACE FUNCTION secondhand.market.similar_min_shared_terms()
RETURNS INT
COMMENT 'Minimum count from the global champion scalar, or prior 2. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN coalesce((SELECT cast(get_json_object(value_or_hyperparams, '$') AS INT)
  FROM secondhand.core.param
  WHERE name = 'similar_min_shared_terms' AND scope = '{}' AND status = 'champion'
  ORDER BY version DESC
  LIMIT 1), 2);

CREATE OR REPLACE FUNCTION secondhand.market.title_terms(title STRING)
RETURNS ARRAY<STRING>
COMMENT 'Shared Unicode title tokenizer for listing reads and DB20 competition word lists. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN filter(split(lower(coalesce(title_terms.title, '')), r'[^\p{L}\p{N}]+'), word -> word <> '');

CREATE OR REPLACE FUNCTION secondhand.market.similar_group(kind STRING, brand STRING, title_terms ARRAY<STRING>)
RETURNS TABLE (observation_id STRING, site STRING, kind STRING, brand_norm STRING, title_terms ARRAY<STRING>, shared_terms INT, n BIGINT, as_of TIMESTAMP)
COMMENT 'Same kind and a different known brand, ranked by distinct shared title words, not attribute equivalence. Requires similar_min_shared_terms and market_min_n group rows. Missing brands and empty titles never match. Only may_model true evidence, never Dupe, live: reads within retention.'
RETURN
WITH candidates AS (
  SELECT o.observation_id, o.site, o.kind, o.brand_norm, o.title_terms,
    size(array_intersect(o.title_terms, similar_group.title_terms)) AS shared_terms, o.read_at
  FROM secondhand.market.listing_obs o
  WHERE o.kind = similar_group.kind
    AND nullif(trim(o.brand_norm), '') IS NOT NULL
    AND nullif(trim(similar_group.brand), '') IS NOT NULL
    AND lower(trim(o.brand_norm)) <> lower(trim(similar_group.brand))
    AND size(o.title_terms) > 0 AND size(similar_group.title_terms) > 0
), matched AS (
  SELECT observation_id, site, kind, brand_norm, title_terms, shared_terms,
    count(*) OVER () AS n, max(read_at) OVER () AS as_of
  FROM candidates
  WHERE shared_terms >= secondhand.market.similar_min_shared_terms()
    AND shared_terms > 0
)
SELECT observation_id, site, kind, brand_norm, title_terms, shared_terms, n, as_of
FROM matched WHERE n >= secondhand.market.market_min_n()
ORDER BY shared_terms DESC, observation_id;
